def html_page() -> str:
    return """<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Traceable Admissions MAS</title><style>body{font-family:system-ui,sans-serif;max-width:1100px;margin:0 auto;padding:28px;background:#f6f7f9;color:#17202a}h1{margin-bottom:4px}p{color:#5b6570}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}section{background:white;border:1px solid #dce1e7;border-radius:8px;padding:18px}textarea,input{width:100%;box-sizing:border-box;border:1px solid #c7ced6;border-radius:5px;padding:10px;font:inherit}textarea{min-height:130px}button{margin-top:10px;background:#1769aa;color:#fff;border:0;border-radius:5px;padding:10px 16px;cursor:pointer}pre{white-space:pre-wrap;overflow:auto;background:#101820;color:#dce9f2;padding:14px;border-radius:5px;max-height:480px}.source{border-top:1px solid #e5e8eb;padding:10px 0}.score{font-size:.85em;color:#53606c}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><h1>Traceable Admissions MAS</h1><p>XML prompt envelope · source registry · relevance/trust validation · audit trace</p><div class='grid'><section><label for='query'>Câu hỏi</label><textarea id='query'>AI support cho lớp học đông thì nên bắt đầu xác định bài toán như thế nào?</textarea><label for='profile'>Candidate profile JSON</label><input id='profile' value='{"education":"student","experience":"basic AI"}'><button onclick='ask()'>Tra cứu</button></section><section><h2>Câu trả lời</h2><div id='answer'>Chưa có truy vấn.</div><h3>Sources</h3><div id='sources'></div></section></div><section><h2>Trace XML</h2><pre id='xml'></pre></section><script>async function ask(){const query=document.getElementById('query').value;let profile={};try{profile=JSON.parse(document.getElementById('profile').value)}catch(e){alert('Profile phải là JSON hợp lệ');return}const r=await fetch('/api/query',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({query,profile})});const d=await r.json();document.getElementById('answer').textContent=d.response;document.getElementById('xml').textContent=d.prompt_xml;document.getElementById('sources').innerHTML=d.sources.map(s=>'<div class=source><b>'+s.source_id+'</b> '+s.title+'<br><span class=score>trust '+s.trust_score+' · '+s.uri+'</span></div>').join('')}</script></body></html>"""
